1	/*
2	 * SWO design tokens — THE canonical source.
3	 *
4	 * Every visual value used by the site is defined here and nowhere else:
5	 * no TypeScript token file, no duplicated Tailwind config. Tailwind v4 reads
6	 * this file through @theme, so each token below is both a CSS custom property
7	 * and a Tailwind utility (e.g. --color-brand-primary -> bg-brand-primary).
8	 *
9	 * Two layers:
10	 *   1. PALETTE  (--palette-*)  raw values. Never referenced by components.
11	 *   2. SEMANTIC (--color-*, --radius-*, ...)  named by purpose. Components use
12	 *      only these.
13	 *
14	 * Name mapping from docs/style-guide.md: dots become dashes, so
15	 * `color.text.primary` is `--color-text-primary` and `radius.card` is
16	 * `--radius-card`. docs/style-guide.md documents each token's value, purpose
17	 * and WCAG evidence; tests/tokens.test.ts fails if the two drift apart.
18	 *
19	 * `static` forces every variable to be emitted even if no utility uses it yet,
20	 * so plain CSS and the design-system showcase can always read them.
21	 */
22	
23	@theme static {
24	  /* Remove Tailwind's default scales so off-system values (bg-red-500, text-sm,
25	     rounded-xl ...) fail to compile instead of silently bypassing the system. */
26	  --color-*: initial;
27	  --font-*: initial;
28	  --text-*: initial;
29	  --font-weight-*: initial;
30	  --leading-*: initial;
31	  --radius-*: initial;
32	  --shadow-*: initial;
33	  --breakpoint-*: initial;
34	  --container-*: initial;
35	
36	  /* ------------------------------------------------------------------ */
37	  /* 1. PALETTE — raw values (components must not reference these)       */
38	  /* ------------------------------------------------------------------ */
39	
40	  /* Neutrals */
41	  --palette-neutral-0: #ffffff;
42	  --palette-neutral-50: #f5f7fa;
43	  --palette-neutral-100: #edf1f5;
44	  --palette-neutral-150: #e2e8ee;
45	  --palette-neutral-200: #dce3ea;
46	  --palette-neutral-500: #7b8794;
47	  --palette-neutral-600: #52607a;
48	  --palette-neutral-900: #101827;
49	
50	  /* Teal (brand) */
51	  --palette-teal-50: #e3f5f2;
52	  --palette-teal-500: #0f9986;
53	  --palette-teal-700: #0b7a6b;
54	  --palette-teal-800: #0a6a5c;
55	  --palette-teal-900: #095c50;
56	
57	  /* Decision-state hues (Green / Amber / Red) */
58	  --palette-green-100: #ddf7e9;
59	  --palette-green-700: #077353;
60	  --palette-amber-100: #fff0cc;
61	  --palette-amber-700: #925600;
62	  --palette-red-100: #fce4e4;
63	  --palette-red-700: #b42318;
64	
65	  /* Informational */
66	  --palette-blue-100: #e0eaff;
67	  --palette-blue-800: #1e40af;
68	
69	  /* ------------------------------------------------------------------ */
70	  /* 2. SEMANTIC — colour                                                */
71	  /* ------------------------------------------------------------------ */
72	
73	  /* Text */
74	  --color-text-primary: var(--palette-neutral-900);
75	  --color-text-secondary: var(--palette-neutral-600);
76	  --color-text-inverse: var(--palette-neutral-0);
77	  --color-text-disabled: var(--palette-neutral-500);
78	
79	  /* Brand */
80	  --color-brand-primary: var(--palette-teal-700);
81	  --color-brand-primary-hover: var(--palette-teal-800);
82	  --color-brand-primary-active: var(--palette-teal-900);
83	  --color-brand-on-primary: var(--palette-neutral-0);
84	  --color-brand-subtle: var(--palette-teal-50);
85	  --color-brand-accent: var(--palette-teal-500);
86	
87	  /* Surfaces */
88	  --color-surface-page: var(--palette-neutral-0);
89	  --color-surface-subtle: var(--palette-neutral-50);
90	  --color-surface-hover: var(--palette-neutral-100);
91	  --color-surface-pressed: var(--palette-neutral-150);
92	  --color-surface-disabled: var(--palette-neutral-100);
93	
94	  /* Borders */
95	  --color-border-default: var(--palette-neutral-200);
96	  --color-border-strong: var(--palette-neutral-500);
97	
98	  /* Workout decision states: Green / Amber / Red.
99	     Semantic only; never decoration. Always paired with a text label + icon. */
100	  --color-status-green-bg: var(--palette-green-100);
101	  --color-status-green-fg: var(--palette-green-700);
102	  --color-status-amber-bg: var(--palette-amber-100);
103	  --color-status-amber-fg: var(--palette-amber-700);
104	  --color-status-red-bg: var(--palette-red-100);
105	  --color-status-red-fg: var(--palette-red-700);
106	
107	  /* General UI feedback. Success / warning / danger deliberately ALIAS the
108	     decision-state tokens so the system has one green, one amber, one red. */
109	  --color-feedback-success-bg: var(--color-status-green-bg);
110	  --color-feedback-success-fg: var(--color-status-green-fg);
111	  --color-feedback-warning-bg: var(--color-status-amber-bg);
112	  --color-feedback-warning-fg: var(--color-status-amber-fg);
113	  --color-feedback-danger-bg: var(--color-status-red-bg);
114	  --color-feedback-danger-fg: var(--color-status-red-fg);
115	  --color-feedback-info-bg: var(--palette-blue-100);
116	  --color-feedback-info-fg: var(--palette-blue-800);
117	
118	  /* Focus */
119	  --color-focus-ring: var(--color-brand-primary);
120	
121	  /* ------------------------------------------------------------------ */
122	  /* 3. Typography                                                       */
123	  /* ------------------------------------------------------------------ */
124	
125	  --font-sans: Inter, ui-sans-serif, system-ui, sans-serif;
126	
127	  --font-weight-regular: 400;
128	  --font-weight-medium: 500;
129	  --font-weight-semibold: 600;
130	  --font-weight-bold: 700;
131	
132	  --text-hero: clamp(2.75rem, 5vw, 4.5rem);
133	  --text-hero--line-height: 1.05;
134	  --text-h2: clamp(2rem, 3.2vw, 3rem);
135	  --text-h2--line-height: 1.15;
136	  --text-h3: 1.25rem;
137	  --text-h3--line-height: 1.2;
138	  --text-body: 1rem;
139	  --text-body--line-height: 1.6;
140	  --text-small: 0.875rem;
141	  --text-small--line-height: 1.5;
142	
143	  --leading-heading: 1.15;
144	  --leading-body: 1.6;
145	
146	  /* ------------------------------------------------------------------ */
147	  /* 4. Spacing, geometry, layout                                        */
148	  /* ------------------------------------------------------------------ */
149	
150	  /* One step = 0.25rem, so Tailwind's numeric utilities line up exactly with
151	     the documented scale: p-4 = space.4 = 1rem. Only the documented steps
152	     (1 2 3 4 6 8 12 16) are permitted; the design-system auditor flags others. */
153	  --spacing: 0.25rem;
154	  --space-1: 0.25rem;
155	  --space-2: 0.5rem;
156	  --space-3: 0.75rem;
157	  --space-4: 1rem;
158	  --space-6: 1.5rem;
159	  --space-8: 2rem;
160	  --space-12: 3rem;
161	  --space-16: 4rem;
162	
163	  --radius-card: 1rem;
164	  --radius-button: 0.625rem;
165	  --radius-control: 0.625rem;
166	  --radius-pill: 9999px;
167	
168	  /* Tailwind's built-in `border` (1px) and `border-2` (2px) are the values of
169	     these two tokens; tests/tokens.test.ts pins them. */
170	  --border-width-default: 1px;
171	  --border-width-strong: 2px;
172	
173	  --shadow-card: 0 1px 2px 0 rgb(16 24 39 / 0.06), 0 1px 3px 0 rgb(16 24 39 / 0.08);
174	  --shadow-raised: 0 4px 6px -1px rgb(16 24 39 / 0.08), 0 10px 24px -4px rgb(16 24 39 / 0.12);
175	
176	  --container-content: 72rem;
177	  --container-prose: 42rem;
178	
179	  /* Mobile-first. The style guide specified no breakpoints; these equal
180	     Tailwind's defaults and are recorded as PROPOSED until Phase D checks
181	     them against the real layout. */
182	  --breakpoint-sm: 40rem;
183	  --breakpoint-md: 48rem;
184	  --breakpoint-lg: 64rem;
185	  --breakpoint-xl: 80rem;
186	
187	  /* ------------------------------------------------------------------ */
188	  /* 5. Interaction                                                      */
189	  /* ------------------------------------------------------------------ */
190	
191	  --focus-ring-width: 3px;
192	  --focus-ring-offset: 2px;
193	  --default-transition-duration: 150ms;
194	  --min-target-size: 2.75rem;
195	}
