1	import type { AnchorHTMLAttributes, ButtonHTMLAttributes, ReactNode } from 'react';
2	import { LoaderCircle } from 'lucide-react';
3	import { cx } from '../lib/cx.ts';
4	
5	export type ButtonVariant = 'primary' | 'secondary' | 'tertiary';
6	
7	const base =
8	  'inline-flex min-h-(--min-target-size) items-center justify-center gap-2 rounded-button ' +
9	  'text-body font-semibold transition-colors';
10	
11	const variants: Record<ButtonVariant, string> = {
12	  primary:
13	    'px-6 py-3 bg-brand-primary text-brand-on-primary ' +
14	    'hover:bg-brand-primary-hover active:bg-brand-primary-active',
15	  secondary:
16	    'px-6 py-3 border border-border-strong bg-surface-page text-text-primary ' +
17	    'hover:bg-surface-hover active:bg-surface-pressed',
18	  tertiary: 'px-4 py-3 text-brand-primary hover:bg-surface-hover active:bg-surface-pressed',
19	};
20	
21	// `disabled:` sorts after `hover:` / `active:`, so a disabled button never
22	// shows a hover or pressed colour.
23	const disabledStyles =
24	  'disabled:cursor-not-allowed disabled:border-transparent disabled:bg-surface-disabled ' +
25	  'disabled:text-text-disabled';
26	
27	interface CommonProps {
28	  variant?: ButtonVariant;
29	  children: ReactNode;
30	}
31	
32	export interface ButtonProps
33	  extends CommonProps, Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'> {
34	  /** Shows a spinner and blocks interaction. The label stays visible. */
35	  loading?: boolean;
36	}
37	
38	/** An action. Use ButtonLink for navigation. */
39	export function Button({
40	  variant = 'primary',
41	  loading = false,
42	  disabled,
43	  type = 'button',
44	  className,
45	  children,
46	  ...rest
47	}: ButtonProps) {
48	  return (
49	    <button
50	      type={type}
51	      // A loading button is disabled so a second activation cannot fire.
52	      disabled={disabled || loading}
53	      aria-busy={loading || undefined}
54	      className={cx(base, variants[variant], disabledStyles, className)}
55	      {...rest}
56	    >
57	      {loading && <LoaderCircle aria-hidden="true" className="size-4 animate-spin" />}
58	      {children}
59	    </button>
60	  );
61	}
62	
63	export interface ButtonLinkProps
64	  extends CommonProps, Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children' | 'href'> {
65	  /** Required: a link without a destination is not a link. */
66	  href: string;
67	}
68	
69	/** Navigation styled like a Button. Renders a real anchor. */
70	export function ButtonLink({ variant = 'primary', className, children, ...rest }: ButtonLinkProps) {
71	  return (
72	    <a className={cx(base, variants[variant], className)} {...rest}>
73	      {children}
74	    </a>
75	  );
76	}
