1	import type { HTMLAttributes, ReactNode } from 'react';
2	import { cx } from '../lib/cx.ts';
3	
4	export type CardVariant = 'outlined' | 'subtle';
5	
6	const variants: Record<CardVariant, string> = {
7	  outlined: 'border border-border-default bg-surface-page shadow-card',
8	  subtle: 'bg-surface-subtle',
9	};
10	
11	export interface CardProps extends Omit<HTMLAttributes<HTMLElement>, 'children'> {
12	  /** Use `article` for self-contained content, `section` only with an accessible name. */
13	  as?: 'div' | 'article' | 'section';
14	  variant?: CardVariant;
15	  children: ReactNode;
16	}
17	
18	export function Card({
19	  as: Element = 'div',
20	  variant = 'outlined',
21	  className,
22	  children,
23	  ...rest
24	}: CardProps) {
25	  return (
26	    <Element className={cx('rounded-card p-6', variants[variant], className)} {...rest}>
27	      {children}
28	    </Element>
29	  );
30	}
