1	import type { HTMLAttributes, ReactNode } from 'react';
2	import { cx } from '../lib/cx.ts';
3	
4	export type SectionTone = 'page' | 'subtle';
5	
6	const tones: Record<SectionTone, string> = {
7	  page: 'bg-surface-page',
8	  subtle: 'bg-surface-subtle',
9	};
10	
11	export interface SectionContainerProps extends Omit<HTMLAttributes<HTMLElement>, 'children'> {
12	  tone?: SectionTone;
13	  /**
14	   * A <section> is only a landmark when it has an accessible name, so pass
15	   * `aria-labelledby` pointing at the SectionHeading id (or `aria-label`).
16	   */
17	  children: ReactNode;
18	}
19	
20	/** Full-width band with a bounded, gutter-padded content column. */
21	export function SectionContainer({
22	  tone = 'page',
23	  className,
24	  children,
25	  ...rest
26	}: SectionContainerProps) {
27	  return (
28	    <section className={cx('py-12 md:py-16', tones[tone], className)} {...rest}>
29	      <div className="mx-auto w-full max-w-content px-4 md:px-6 lg:px-8">{children}</div>
30	    </section>
31	  );
32	}
