1	import type { ReactNode } from 'react';
2	import { cx } from '../lib/cx.ts';
3	
4	const sizes = {
5	  1: 'text-hero font-bold',
6	  2: 'text-h2 font-bold',
7	  3: 'text-h3 font-semibold',
8	} as const;
9	
10	export interface SectionHeadingProps {
11	  /** Document outline level. Visual size follows the level, so pick by structure. */
12	  level?: 1 | 2 | 3;
13	  title: ReactNode;
14	  eyebrow?: string;
15	  description?: ReactNode;
16	  align?: 'start' | 'center';
17	  /** Set so a parent section can reference it with aria-labelledby. */
18	  id?: string;
19	  className?: string;
20	}
21	
22	export function SectionHeading({
23	  level = 2,
24	  title,
25	  eyebrow,
26	  description,
27	  align = 'start',
28	  id,
29	  className,
30	}: SectionHeadingProps) {
31	  const Heading = `h${level}` as const;
32	  return (
33	    <div
34	      className={cx(
35	        'flex max-w-prose flex-col gap-3',
36	        align === 'center' && 'mx-auto items-center text-center',
37	        className,
38	      )}
39	    >
40	      {eyebrow && (
41	        <p className="text-small font-semibold uppercase text-brand-primary">{eyebrow}</p>
42	      )}
43	      <Heading id={id} className={cx(sizes[level], 'text-text-primary')}>
44	        {title}
45	      </Heading>
46	      {description && <p className="text-body text-text-secondary">{description}</p>}
47	    </div>
48	  );
49	}
