1	import type { ReactNode } from 'react';
2	import { CircleCheck, CircleX, TriangleAlert } from 'lucide-react';
3	import { cx } from '../lib/cx.ts';
4	
5	/** The three workout decision states. Use for decision meaning only. */
6	export type WorkoutStatus = 'green' | 'amber' | 'red';
7	
8	interface StatusMeta {
9	  /** Colour name, announced to screen readers. */
10	  colour: string;
11	  /** Default visible label. Meaning comes from this text, never from colour. */
12	  label: string;
13	  Icon: typeof CircleCheck;
14	  className: string;
15	}
16	
17	// Distinct SHAPES as well as colours: circle+check, triangle, circle+cross.
18	export const STATUS_META: Record<WorkoutStatus, StatusMeta> = {
19	  green: {
20	    colour: 'Green',
21	    label: 'Optimal zone',
22	    Icon: CircleCheck,
23	    className: 'bg-status-green-bg text-status-green-fg border-status-green-fg',
24	  },
25	  amber: {
26	    colour: 'Amber',
27	    label: 'Caution zone',
28	    Icon: TriangleAlert,
29	    className: 'bg-status-amber-bg text-status-amber-fg border-status-amber-fg',
30	  },
31	  red: {
32	    colour: 'Red',
33	    label: 'High-risk flag',
34	    Icon: CircleX,
35	    className: 'bg-status-red-bg text-status-red-fg border-status-red-fg',
36	  },
37	};
38	
39	export interface StatusBadgeProps {
40	  status: WorkoutStatus;
41	  /** Overrides the default label. It must still say what the state means. */
42	  children?: ReactNode;
43	  className?: string;
44	}
45	
46	export function StatusBadge({ status, children, className }: StatusBadgeProps) {
47	  const { colour, label, Icon, className: tone } = STATUS_META[status];
48	  return (
49	    <span
50	      data-status={status}
51	      className={cx(
52	        'inline-flex items-center gap-2 rounded-pill border px-3 py-1',
53	        'text-small font-semibold',
54	        tone,
55	        className,
56	      )}
57	    >
58	      <Icon aria-hidden="true" className="size-4 shrink-0" />
59	      <span className="sr-only">{colour} status:</span> {children ?? label}
60	    </span>
61	  );
62	}
