1	import { createContext, useContext, useId } from 'react';
2	import type { InputHTMLAttributes, ReactNode, SelectHTMLAttributes } from 'react';
3	import { CircleX } from 'lucide-react';
4	import { cx } from '../lib/cx.ts';
5	
6	interface FieldContextValue {
7	  id: string;
8	  describedBy: string | undefined;
9	  invalid: boolean;
10	  required: boolean;
11	}
12	
13	const FieldContext = createContext<FieldContextValue | null>(null);
14	
15	function useField(component: string): FieldContextValue {
16	  const context = useContext(FieldContext);
17	  if (!context) throw new Error(`${component} must be rendered inside <FormField>`);
18	  return context;
19	}
20	
21	export interface FormFieldProps {
22	  label: string;
23	  hint?: string;
24	  /** When set, the field is marked invalid and the message is announced with it. */
25	  error?: string;
26	  required?: boolean;
27	  children: ReactNode;
28	  className?: string;
29	}
30	
31	/**
32	 * Wires a visible label, optional hint and optional error to the control inside
33	 * it, so every control has an accessible name and description.
34	 */
35	export function FormField({
36	  label,
37	  hint,
38	  error,
39	  required = false,
40	  children,
41	  className,
42	}: FormFieldProps) {
43	  const id = useId();
44	  const hintId = hint ? `${id}-hint` : undefined;
45	  const errorId = error ? `${id}-error` : undefined;
46	  const describedBy = [hintId, errorId].filter(Boolean).join(' ') || undefined;
47	
48	  return (
49	    <FieldContext.Provider value={{ id, describedBy, invalid: Boolean(error), required }}>
50	      <div className={cx('flex flex-col gap-2', className)}>
51	        <label htmlFor={id} className="text-small font-semibold text-text-primary">
52	          {label}
53	          {required && (
54	            <>
55	              <span aria-hidden="true"> *</span> <span className="sr-only">(required)</span>
56	            </>
57	          )}
58	        </label>
59	        {hint && (
60	          <p id={hintId} className="text-small text-text-secondary">
61	            {hint}
62	          </p>
63	        )}
64	        {children}
65	        {error && (
66	          // Icon + text, so the error is not signalled by colour alone.
67	          <p
68	            id={errorId}
69	            className="flex items-center gap-2 text-small font-medium text-feedback-danger-fg"
70	          >
71	            <CircleX aria-hidden="true" className="size-4 shrink-0" />
72	            <span>
73	              <span className="sr-only">Error:</span> {error}
74	            </span>
75	          </p>
76	        )}
77	      </div>
78	    </FieldContext.Provider>
79	  );
80	}
81	
82	const controlStyles =
83	  'min-h-(--min-target-size) w-full rounded-control border bg-surface-page px-3 py-2 ' +
84	  'text-body text-text-primary placeholder:text-text-secondary ' +
85	  'disabled:cursor-not-allowed disabled:bg-surface-disabled disabled:text-text-disabled';
86	
87	function borderFor(invalid: boolean): string {
88	  // The invalid border is thicker as well as red: a second non-colour cue.
89	  return invalid ? 'border-2 border-feedback-danger-fg' : 'border-border-strong';
90	}
91	
92	export type TextInputProps = Omit<InputHTMLAttributes<HTMLInputElement>, 'id' | 'required'>;
93	
94	export function TextInput({ className, ...rest }: TextInputProps) {
95	  const field = useField('TextInput');
96	  return (
97	    <input
98	      id={field.id}
99	      required={field.required}
100	      aria-invalid={field.invalid || undefined}
101	      aria-describedby={field.describedBy}
102	      className={cx(controlStyles, borderFor(field.invalid), className)}
103	      {...rest}
104	    />
105	  );
106	}
107	
108	export interface SelectProps extends Omit<
109	  SelectHTMLAttributes<HTMLSelectElement>,
110	  'id' | 'required'
111	> {
112	  children: ReactNode;
113	}
114	
115	export function Select({ className, children, ...rest }: SelectProps) {
116	  const field = useField('Select');
117	  return (
118	    <select
119	      id={field.id}
120	      required={field.required}
121	      aria-invalid={field.invalid || undefined}
122	      aria-describedby={field.describedBy}
123	      className={cx(controlStyles, borderFor(field.invalid), className)}
124	      {...rest}
125	    >
126	      {children}
127	    </select>
128	  );
129	}
