1	@import 'tailwindcss';
2	@import './tokens.css';
3	
4	/* Global behaviour that cannot be expressed as component utilities.
5	   Values come only from tokens.css. */
6	@layer base {
7	  html {
8	    font-family: var(--font-sans);
9	    -webkit-text-size-adjust: 100%;
10	  }
11	
12	  body {
13	    margin: 0;
14	    background-color: var(--color-surface-page);
15	    color: var(--color-text-primary);
16	    font-size: var(--text-body);
17	    line-height: var(--leading-body);
18	  }
19	
20	  /* One consistent, always-visible keyboard focus indicator. The offset leaves
21	     a gap so the ring stays distinguishable on top of a same-hue button. */
22	  :where(a, button, input, select, textarea, summary, [tabindex]):focus-visible {
23	    outline: var(--focus-ring-width) solid var(--color-focus-ring);
24	    outline-offset: var(--focus-ring-offset);
25	  }
26	
27	  @media (prefers-reduced-motion: reduce) {
28	    *,
29	    *::before,
30	    *::after {
31	      animation-duration: 0.01ms !important;
32	      animation-iteration-count: 1 !important;
33	      transition-duration: 0.01ms !important;
34	      scroll-behavior: auto !important;
35	    }
36	  }
37	}
